parameters.jsCode:
const members = $('Fetch All Members').all() || [];
const atRisk = [];
const healthy = [];

for (const member of members) {
  const m = member.json;
  const daysSinceUpdate = Math.floor((Date.now() - new Date(m.updated_at || m.created_at).getTime()) / (24*60*60*1000));

  let healthScore = 100;
  let riskLevel = 'low';
  const signals = [];

  // Inactivity decay
  if (daysSinceUpdate > 7) { healthScore -= 15; signals.push('7+ jours sans activite'); }
  if (daysSinceUpdate > 14) { healthScore -= 20; signals.push('14+ jours sans activite'); }
  if (daysSinceUpdate > 21) { healthScore -= 25; signals.push('21+ jours sans activite'); }
  if (daysSinceUpdate > 30) { healthScore -= 30; signals.push('30+ jours - risque churn eleve'); }

  // Determine risk level
  if (healthScore <= 30) riskLevel = 'critical';
  else if (healthScore <= 50) riskLevel = 'high';
  else if (healthScore <= 70) riskLevel = 'medium';

  if (riskLevel !== 'low') {
    atRisk.push({
      id: m.id,
      first_name: m.first_name,
      email: m.email,
      health_score: healthScore,
      risk_level: riskLevel,
      days_inactive: daysSinceUpdate,
      signals
    });
  } else {
    healthy.push(m.id);
  }
}

return {
  json: {
    date: new Date().toISOString().split('T')[0],
    total_members: members.length,
    healthy_count: healthy.length,
    at_risk_count: atRisk.length,
    critical: atRisk.filter(m => m.risk_level === 'critical').length,
    high: atRisk.filter(m => m.risk_level === 'high').length,
    medium: atRisk.filter(m => m.risk_level === 'medium').length,
    at_risk_members: atRisk.slice(0, 20)
  }
};

