const churnData = $('Detect Churn Risk').item.json;
const aiResponse = $input.item.json.message.content;
let retention;
try { retention = JSON.parse(aiResponse); } catch (e) { retention = { retention_actions: [] }; }

return {
  json: {
    report_type: 'churn_detection',
    date: churnData.date,
    agent_id: 'retention-specialist',
    workflow_id: 'WF-RETAIN-CHURN',
    summary: { total: churnData.total_members, healthy: churnData.healthy_count, at_risk: churnData.at_risk_count, critical: churnData.critical, high: churnData.high, medium: churnData.medium },
    actions: retention.retention_actions || []
  }
};

